import { Card, CardContent } from "@/registry/erbium/ui/card";
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/registry/erbium/ui/carousel";

const CarouselSize = () => (
  <Carousel
    opts={{
      align: "start",
    }}
    className="w-full max-w-sm"
  >
    <CarouselContent>
      {Array.from({ length: 5 }).map((_, index) => (
        <CarouselItem key={index} className="md:basis-1/2 lg:basis-1/3">
          <div className="p-1">
            <Card className="aspect-square">
              <CardContent className="flex min-h-0 flex-1 items-center justify-center">
                <span className="text-display font-semibold">{index + 1}</span>
              </CardContent>
            </Card>
          </div>
        </CarouselItem>
      ))}
    </CarouselContent>
    <CarouselPrevious />
    <CarouselNext />
  </Carousel>
);

export default CarouselSize;

import ExampleCarouselSize from "../examples/carousel-size";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleCarouselSize />
  </div>
);

export default Example;
